package com.trombokendu.chronos.analytics;import java.time.*;import java.util.*;import java.util.random.*;public final class BootstrapModel implements SpendModel{private final List<List<Double>> buckets=new ArrayList<>();private final double[] pooled;public BootstrapModel(Map<DayOfWeek,List<Double>> data){for(DayOfWeek d:DayOfWeek.values()){List<Double>x=List.copyOf(data.getOrDefault(d,List.of()));buckets.add(x);}pooled=buckets.stream().flatMap(List::stream).mapToDouble(Double::doubleValue).toArray();}public double sampleDaily(RandomGenerator r,LocalDate d){List<Double>b=buckets.get(d.getDayOfWeek().getValue()-1);if(!b.isEmpty())return b.get(r.nextInt(b.size()));return pooled.length==0?0:pooled[r.nextInt(pooled.length)];}}
